// Clinical Specialty lessons 1–5: the event, choosing a career and skill, research, interviews.
const RULES=['HOSA Clinical Specialty 2026–27 guidelines and rating sheets (October 2026)','https://hosa.org/wp-content/uploads/2026/10/CS-26-27-Oct-26.pdf'];
const UPLOAD=['HOSA: competitive event digital uploads','https://hosa.org/competitive-event-digital-uploads/'];
const NCHSE=['National Consortium for Health Science Education','https://www.healthscienceconsortium.org/'];
const EHC=['Explore Health Careers (career profiles)','https://explorehealthcareers.org/'];
const OOH=['U.S. Bureau of Labor Statistics: Occupational Outlook Handbook, Healthcare','https://www.bls.gov/ooh/healthcare/home.htm'];
const ONET=['O*NET OnLine: occupation details, tasks and skills','https://www.onetonline.org/'];
const COS=['CareerOneStop: licenses and certifications finder','https://www.careeronestop.org/Toolkit/Training/find-licenses.aspx'];
const HIPAA=['HHS: summary of the HIPAA Privacy Rule','https://www.hhs.gov/hipaa/for-professionals/privacy/laws-regulations/index.html'];
const q=(p,a,b,c,d,e)=>[p,[a,b,c,d],e];
const match=(title,pairs)=>({t:'w',kind:'match',title,pairs});
const order=(title,steps)=>({t:'w',kind:'order',title,steps});
